WITH metrics AS (SELECT id, dept_id, manager_id, salary, is_remote, AVG(salary) OVER (PARTITION BY level ORDER BY hire_date ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS salary_avg_2, SUM(salary) OVER (ORDER BY hire_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary FROM employees) SELECT CASE WHEN cumulative_salary >= 617513 THEN 'LARGE' ELSE 'SMALL' END AS cumulative_salary_tier, dept_id, CASE WHEN salary >= 162000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, MIN(salary_avg_2) AS min_salary_avg_2, MAX(salary_avg_2) AS max_salary_avg_2 FROM metrics GROUP BY ROLLUP (CASE WHEN cumulative_salary >= 617513 THEN 'LARGE' ELSE 'SMALL' END, dept_id, CASE WHEN salary >= 162000 THEN 'HIGH' ELSE 'LOW' END) ORDER BY max_salary_avg_2 ASC NULLS FIRST
